; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpc (Amstrad CPC - direct hardware, no firmware), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 255		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 only when the library itself is built as a ROM (ntcRomAsm)

ntc_start:
			di
			call ntc_rj_find		; Library: ROM - find the ROM, patch the jump block
			jr nc, ntc_rj_ok
			ei
			ret				; no ROM (the message is shown): back to the caller
ntc_rj_ok:
			di				; (KL ROM SELECT lets interrupts in again)
			ld hl, ntc_rj_exit
			push hl			; End comes back here: the caller's ROM selection again
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld ix, ntc_go
			jp ntc_plat_irqon		; interrupt handler for normal mode
ntc_go:
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_scrinit		; mode 1, ROMs off, clear screen

			; Main.bas 3: n = 42
			dw kw_ltov, 42, var_n

			; Main.bas 4: Print "hello"; n, "x"
			dw p_stdio_putstr_c, str0
			dw kw_strcstr, stmp0, var_n
			dw p_stdio_putstr_c, stmp0
			dw p_stdio_putstr_c, str2
			dw p_stdio_newline_c

			; Main.bas 5: Cls
			dw p_stdio_cls_c

			; Main.bas 6: Locate 3, 4
			dw p_stdio_locate_c, lit_3, lit_4

			; Main.bas 7: Input "name"; s
			dw p_stdio_putstr_c, str3
			dw p_stdio_getline_c, var_s

			; Main.bas 8: Print s
			dw p_stdio_putstr_c, var_s
			dw p_stdio_newline_c

			; Main.bas 9: k$ = Inkey$
			dw p_stdio_getkey_c
			dw kw_strchr, stmp0, var_stdio_getkey_getkey
			dw kw_strcpy, var_k, stmp0

			; Main.bas 10: Print k$; Inkey
			dw p_stdio_putstr_c, var_k
			dw p_stdio_getkey_c
			dw kw_strcstr, stmp0, var_stdio_getkey_getkey
			dw p_stdio_putstr_c, stmp0
			dw p_stdio_newline_c

			; Main.bas 11: Input "num"; n
			dw p_stdio_putstr_c, str4
			dw p_stdio_getline_c, stmp0
			dw kw_strval, stmp0, var_n

			; Main.bas 12: Print n + 1
			dw kw_addl, var_n, 1, tmp0
			dw kw_strcstr, stmp0, tmp0
			dw p_stdio_putstr_c, stmp0
			dw p_stdio_newline_c

			; Main.bas 13: Print "lines "; StdIO.Lines
			dw p_stdio_putstr_c, str5
			dw kw_strcstr, stmp0, var_stdio_lines
			dw p_stdio_putstr_c, stmp0
			dw p_stdio_newline_c

			; Main.bas 14: Print "Press a key";
			dw p_stdio_putstr_c, str6

			; Main.bas 15: Do : Frame : Loop Until Inkey <> 0
do1_t:
			dw kw_frame
			dw p_stdio_getkey_c
			dw kw_cpnevl, var_stdio_getkey_getkey, 0
			dw kw_goto_iffalse_n, do1_t
do1_e:

			; Main.bas 16: Print
			dw p_stdio_newline_c
			dw kw_stop

; ============================================================
; sub putstr (normal mode)
; ============================================================

p_stdio_putstr:

			; StdIO.cls 6: Print "<"; UCase$(s); ">";
			dw kw_strucase, stmp1, var_stdio_putstr_s
			dw kw_printzoscii
			dw glyph_3C, 0		; "<"
			dw kw_printstrvar, stmp1
			dw kw_printzoscii
			dw glyph_3E, 0		; ">"
			dw p_stdio_putstr_r

; ============================================================
; sub newline (normal mode)
; ============================================================

p_stdio_newline:

			; StdIO.cls 10: Print
			dw kw_printnl

			; StdIO.cls 11: Lines = Lines + 1
			dw kw_inc, var_stdio_lines
			dw p_stdio_newline_r

; ============================================================
; sub getline (normal mode)
; ============================================================

p_stdio_getline:

			; StdIO.cls 15: Input s
			dw kw_printzoscii
			dw glyph_3F, glyph_20, 0		; "? "
			dw kw_inputstr, var_stdio_getline_s

			; StdIO.cls 16: s = s & "!"
			dw kw_strcat, var_stdio_getline_s, str7
			dw p_stdio_getline_r

; ============================================================
; function getkey (normal mode)
; ============================================================

p_stdio_getkey:

			; StdIO.cls 20: GetKey = 81
			dw kw_ltov, 81, var_stdio_getkey_getkey
			dw p_stdio_getkey_r

; ============================================================
; sub cls (normal mode)
; ============================================================

p_stdio_cls:

			; StdIO.cls 24: Print "[cls]"
			dw kw_printzoscii
			dw glyph_5B, glyph_63, glyph_6C, glyph_73, glyph_5D, 1, 0		; "[cls]\n"
			dw p_stdio_cls_r

; ============================================================
; sub locate (normal mode)
; ============================================================

p_stdio_locate:

			; StdIO.cls 28: Print "[at "; x; ","; y; "]";
			dw kw_printzoscii
			dw glyph_5B, glyph_61, glyph_74, glyph_20, 0		; "[at "
			dw kw_printint, var_stdio_locate_x
			dw kw_printzoscii
			dw glyph_2C, 0		; ","
			dw kw_printint, var_stdio_locate_y
			dw kw_printzoscii
			dw glyph_5D, 0		; "]"
			dw p_stdio_locate_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================


p_stdio_putstr_c:		; call putstr (normal)
			pop hl			; s
			ld de, var_stdio_putstr_s
			ld b, 255
p_stdio_putstr_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_stdio_putstr_si0_e
			inc hl
			inc de
			djnz p_stdio_putstr_si0
			xor a
			ld (de), a
p_stdio_putstr_si0_e:
			ld (p_stdio_putstr_rs), sp
			ld sp, p_stdio_putstr
			jp ntc_xn
p_stdio_putstr_r:		; end of putstr
			ld sp, (p_stdio_putstr_rs)
			jp ntc_xn
p_stdio_newline_c:		; call newline (normal)
			ld (p_stdio_newline_rs), sp
			ld sp, p_stdio_newline
			jp ntc_xn
p_stdio_newline_r:		; end of newline
			ld sp, (p_stdio_newline_rs)
			jp ntc_xn
p_stdio_getline_c:		; call getline (normal)
			pop hl			; s
			ld (p_stdio_getline_a0), hl
			ld de, var_stdio_getline_s
			ld b, 255
p_stdio_getline_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_stdio_getline_si0_e
			inc hl
			inc de
			djnz p_stdio_getline_si0
			xor a
			ld (de), a
p_stdio_getline_si0_e:
			ld (p_stdio_getline_rs), sp
			ld sp, p_stdio_getline
			jp ntc_xn
p_stdio_getline_r:		; end of getline
			ld de, (p_stdio_getline_a0)
			ld hl, var_stdio_getline_s
			dec de
			ld a, (de)		; the destination's capacity
			ld b, a
			inc de
p_stdio_getline_so0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_stdio_getline_so0_e
			inc hl
			inc de
			djnz p_stdio_getline_so0
			xor a
			ld (de), a
p_stdio_getline_so0_e:
			ld sp, (p_stdio_getline_rs)
			jp ntc_xn
p_stdio_getkey_c:		; call getkey (normal)
			ld hl, 0
			ld (var_stdio_getkey_getkey), hl
			ld (p_stdio_getkey_rs), sp
			ld sp, p_stdio_getkey
			jp ntc_xn
p_stdio_getkey_r:		; end of getkey
			ld sp, (p_stdio_getkey_rs)
			jp ntc_xn
p_stdio_cls_c:		; call cls (normal)
			ld (p_stdio_cls_rs), sp
			ld sp, p_stdio_cls
			jp ntc_xn
p_stdio_cls_r:		; end of cls
			ld sp, (p_stdio_cls_rs)
			jp ntc_xn
p_stdio_locate_c:		; call locate (normal)
			pop hl			; x
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_stdio_locate_x), de
			pop hl			; y
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_stdio_locate_y), de
			ld (p_stdio_locate_rs), sp
			ld sp, p_stdio_locate
			jp ntc_xn
p_stdio_locate_r:		; end of locate
			ld sp, (p_stdio_locate_rs)
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_n:			dw 0
			db 40			; capacity
var_s:			ds 41
			db 40			; capacity
var_k:			ds 41
var_stdio_getkey_getkey:			dw 0
var_stdio_lines:			dw 0
p_stdio_putstr_rs:			dw 0
			db 255			; capacity
var_stdio_putstr_s:			ds 256
p_stdio_newline_rs:			dw 0
p_stdio_getline_rs:			dw 0
			db 255			; capacity
var_stdio_getline_s:			ds 256
p_stdio_getline_a0:			dw 0
p_stdio_getkey_rs:			dw 0
p_stdio_cls_rs:			dw 0
p_stdio_locate_rs:			dw 0
var_stdio_locate_x:			dw 0
var_stdio_locate_y:			dw 0
tmp0:			dw 0
			db 255			; capacity
stmp0:			ds 256
			db 255			; capacity
stmp1:			ds 256

; numbers passed by address (read only)
lit_3:			dw 3
lit_4:			dw 4

; ============================================================
; ZOSCII glyphs - each points at its 8 byte bitmap in ntc_font
; ============================================================

glyph_20			equ ntc_font + 0		; " "
glyph_2C			equ ntc_font + 96		; ","
glyph_3C			equ ntc_font + 224		; "<"
glyph_3E			equ ntc_font + 240		; ">"
glyph_3F			equ ntc_font + 248		; "?"
glyph_5B			equ ntc_font + 472		; "["
glyph_5D			equ ntc_font + 488		; "]"
glyph_61			equ ntc_font + 520		; "a"
glyph_63			equ ntc_font + 536		; "c"
glyph_6C			equ ntc_font + 608		; "l"
glyph_73			equ ntc_font + 664		; "s"
glyph_74			equ ntc_font + 672		; "t"

; ============================================================
; Strings
; ============================================================

str0:			db "hello", 0
str1:			db "x", 0
str2:			db " x", 0
str3:			db "name? ", 0
str4:			db "num? ", 0
str5:			db "lines ", 0
str6:			db "Press a key", 0
str7:			db "!", 0

; ============================================================
; Keyword library (rom)
; ============================================================

; Library: ROM - the keyword library is in the ROM NTC CPC (NTCCPC.ROM).
; Its routines: this jump block, the numbers made into addresses by the ROM at the start.
; Its variables and constants: fixed addresses (RAM #8800 - #A5EF is the ROM's).
ntc_rj_block:
kw_stop:		jp 1
ntc_xn:		jp 2
kw_goto_iffalse_n:	jp 11
kw_ltov:		jp 47
kw_inc:		jp 51
kw_addl:		jp 54
kw_cpnevl:	jp 98
kw_strcpy:	jp 122
kw_strcat:	jp 124
kw_printzoscii:	jp 129
kw_printstrvar:	jp 130
kw_printint:	jp 132
kw_printnl:	jp 139
kw_inputstr:	jp 142
kw_scrinit:	jp 147
kw_frame:	jp 153
kw_strchr:	jp 175
kw_strcstr:	jp 176
kw_strucase:	jp 181
kw_strval:	jp 187
ntc_plat_irqon:	jp 308
NTC_RJ_N	equ 21		; entries
ntc_csp	equ #8800		; ROM data
ntc_font	equ #948E		; ROM bss
ntc_nmode	equ #8807		; ROM data
ntc_v_free	equ #88C1		; ROM data
ntc_v_romen	equ #88C7		; ROM data
ntc_v_romold	equ #88C9		; ROM data
ntc_v_stamp	equ #88C5		; ROM data
ntc_v_start	equ #88C3		; ROM data
			ASSERT ntc_free <= #8800, "Library: ROM - the program and its arrays must end below #8800 (the ROM's RAM)"

; the start: find the ROM in slots 0 - 31, have it patch the jump block. NC = ready;
; C = not there / too old (the message is shown, the caller's ROM selection is back)
ntc_rj_find:
			ld c, 0
			call #B90F		; KL ROM SELECT: B / C = the caller's state and selection
			ld (ntc_rj_old), bc
			ld c, 0
ntc_rj_next:
			push bc
			call #B90F		; KL ROM SELECT: ROM C
			pop bc
			ld a, (#C000)
			cp 1				; a background ROM?
			jr nz, ntc_rj_skip
			ld hl, (#C004)		; its names
			ld a, h
			cp #C0
			jr c, ntc_rj_skip
ntc_rj_name:
			ld a, (hl)
			inc hl
			or a
			jr nz, ntc_rj_name		; to the 0 after the names
			ld de, ntc_rj_sig
			ld b, ntc_rj_sige - ntc_rj_sig
ntc_rj_cmp:
			ld a, (de)
			cp (hl)
			jr nz, ntc_rj_skip
			inc de
			inc hl
			djnz ntc_rj_cmp
			ld e, (hl)
			inc hl
			ld d, (hl)			; its patcher
			ld (ntc_rj_call + 1), de
			ld a, c				; its slot
			ld hl, ntc_rj_block
			ld bc, NTC_RJ_N
ntc_rj_call:
			call 0				; HL = jump block, BC = entries, A = slot; C: DE = a number it hasn't got
			jr c, ntc_rj_lacks
			ld hl, ntc_free
			ld (ntc_v_free), hl
			ld hl, ntc_start
			ld (ntc_v_start), hl
			ld hl, 0
			ld (ntc_v_stamp), hl
			ld a, 0
			ld (ntc_v_romen), a
			ld a, (ntc_rj_old)
			ld (ntc_v_romold), a
			or a				; NC: ready
			ret
ntc_rj_skip:
			inc c
			ld a, c
			cp 32
			jr c, ntc_rj_next
			ld hl, ntc_rj_tnf
			jr ntc_rj_fail
ntc_rj_lacks:
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tlk
ntc_rj_fail:
			push hl
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT: the caller's selection again
			pop hl
			call ntc_rj_puts
			ld hl, ntc_rj_tlk
			or a
			sbc hl, de			; (DE: past the message shown)
			jr nz, ntc_rj_nl
			ld a, (ntc_rj_num + 1)
			call ntc_rj_hex
			ld a, (ntc_rj_num)
			call ntc_rj_hex
ntc_rj_nl:
			ld hl, ntc_rj_tnl
			call ntc_rj_puts
			ei
			call #BB06		; KM WAIT CHAR: a key first (a RUN" program's return resets the machine)
			di
			scf
			ret
ntc_rj_puts:				; HL = text, 0 ends; DE = its start
			ld d, h
			ld e, l
ntc_rj_pl:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_rj_pl
ntc_rj_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_rj_dig
			pop af
ntc_rj_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
; End: the caller's ROM selection again, then back to the caller
ntc_rj_exit:
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT
			ret
ntc_rj_old:		dw 0			; the caller's ROM selection (C) and state (B)
ntc_rj_num:		dw 0
ntc_rj_sig:		db "NTC", 1, "CPC", 0	; the ROM's NTC block
ntc_rj_sige:
ntc_rj_tnf:		db "ROM NTC CPC (NTCCPC.ROM) not found", 0
ntc_rj_tlk:		db "ROM NTC CPC too old: no routine #", 0
ntc_rj_tnl:		db 13, 10, "Press a key", 13, 10, 0

ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bss		equ ntc_end
ntc_bss_size	equ 0
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
			SAVEAMSDOS "OWNSTDIO.BIN", ntc_start, ntc_end - ntc_start, ntc_start
